def prime_factors(n):
    factorization = []
    for p in range(int(math.floor(math.sqrt(n))), -1, -1):
        if n % p == 0:
            factorization.append(p)
            while n % p == 0:
                n //= p
    if n > 1:
        factorization.append(n)
    return factorization
